import subprocess
vals=[("nil","nil"),("bool","true"),("int","999"),("float","-999.0"),("char","'z'"),("string","\"a\""),("array","[999]"),("dict","@[z: 999]"),("function","function() end"),("error","std.error(\"z\",\"z\")")]
def first_type(a,b):
    script=f"let a=[{a},{b}]\nstd.sort(a)\nstd.print(std.type(a[0]))\n"
    r=subprocess.run(["./executable"], input=script, capture_output=True, text=True, timeout=5)
    return r.stdout.strip(), r.stderr.strip()
for i,(n1,v1) in enumerate(vals):
    row=[]
    for n2,v2 in vals:
        t,err=first_type(v1,v2)
        row.append(t if not err else "ERR")
    print(n1, row)
