use rand::{SeedableRng, Rng};
use rand::rngs::{StdRng, SmallRng};
use rand_chacha::{ChaCha8Rng, ChaCha12Rng, ChaCha20Rng};
fn show<T: SeedableRng + Rng>(name:&str, seed:u64) {
    let mut rng = T::seed_from_u64(seed);
    print!("{} f64:", name);
    for _ in 0..5 { print!(" {:?}", rng.gen::<f64>()); }
    println!();
    let mut rng = T::seed_from_u64(seed);
    print!("{} randint1-10:", name);
    for _ in 0..5 { print!(" {:?}", rng.gen_range(1..=10)); }
    println!();
    let mut rng = T::seed_from_u64(seed);
    print!("{} randint0-100 incl:", name);
    for _ in 0..5 { print!(" {:?}", rng.gen_range(0..=100)); }
    println!();
    let mut rng = T::seed_from_u64(seed);
    print!("{} randint0-100 excl:", name);
    for _ in 0..5 { print!(" {:?}", rng.gen_range(0..100)); }
    println!();
}
fn main(){
 for seed in [42u64,0,12345] {
   println!("SEED {}",seed);
   show::<StdRng>("StdRng",seed);
   show::<SmallRng>("SmallRng",seed);
   show::<ChaCha8Rng>("ChaCha8",seed);
   show::<ChaCha12Rng>("ChaCha12",seed);
   show::<ChaCha20Rng>("ChaCha20",seed);
 }
}
EOF
cd /tmp/randtest && cargo run --offline 2>/dev/null"}

