# ---------- IO ----------
class LineWriter:
    def __init__(self,fd=1):
        self.fd=fd; self.buf=bytearray(); self.broken=False; self.capacity=1024
        self.lock=threading.Lock()
    def _write_all(self,data):
        while data:
            n=os.write(self.fd,data)
            data=data[n:]
    def write(self,data,pos=None):
        if not data: return
        if isinstance(data,str): data=data.encode('utf-8','surrogateescape')
        with self.lock:
            try:
                idx=data.rfind(b'\n')
                if idx>=0:
                    towrite=bytes(self.buf)+data[:idx+1]
                    self.buf=bytearray()
                    if towrite: self._write_all(towrite)
                    rest=data[idx+1:]
                    if rest: self._write_no_newline(rest)
                else:
                    self._write_no_newline(data)
            except OSError as e:
                self.broken=True
                raise HushPanic(pos, io_error_text(e))
            except BrokenPipeError as e:
                self.broken=True
                raise HushPanic(pos, io_error_text(e))
    def _write_no_newline(self,data):
        if len(data)>=self.capacity:
            if self.buf:
                self._write_all(bytes(self.buf)); self.buf=bytearray()
            self._write_all(data)
        elif len(self.buf)+len(data)>self.capacity:
            if self.buf:
                self._write_all(bytes(self.buf))
            self.buf=bytearray(data)
        else:
            self.buf+=data
