from hush import ChaCha8
info=[(42,1,10),(0,0,100),(7,0,2),(7,0,3),(99,0,999)]
lines=open('/tmp/randseq.txt').read().splitlines()
cand=[]
for (seed,lo,hi),line in zip(info,lines):
    vals=[tuple(map(int,tok.split(':'))) for tok in line.split('|')[1].split()]
    r=ChaCha8.from_u64(seed); xs=[r.next_u64() for _ in range(60)]; w=hi-lo+1; prev=0
    for res,cum in vals:
        for j,x in enumerate(xs[prev:cum]): cand.append((w,x,j==cum-prev-1))
        prev=cum
# features returning float in [0,1]
def make_feats(w,x):
    f={}
    p=x*w
    f['low64']=((p)&((1<<64)-1))/2**64
    f['x']=x/2**64
    for shift in [0,8,16,24,32,40,48,56]:
        for bits in [8,16,32]:
            if shift+bits<=64: f[f'chunk{shift}_{bits}']=((x>>shift)&((1<<bits)-1))/(1<<bits)
    for bits in [8,16,32,64]:
        mask=(1<<bits)-1
        f[f'prod_low{bits}']=(p&mask)/(1<<bits)
        f[f'hi{bits}prod_low']=((((x>>(64-bits)) if bits<64 else x)*w)&mask)/(1<<bits) if bits<=32 else f['low64']
        f[f'lo{bits}prod_low']=(((x&mask)*w)&mask)/(1<<bits)
    f['xmodw']=(x%w)/w
    f['hi32modw']=((x>>32)%w)/w
    f['lo32modw']=((x&0xffffffff)%w)/w
    f['lemfrac']=f['low64']
    return f
names=list(make_feats(10,123).keys())
best=[]
for name in names:
    valsA=[make_feats(w,x)[name] for w,x,a in cand if a]; valsR=[make_feats(w,x)[name] for w,x,a in cand if not a]
    # best threshold accuracy either direction
    allv=sorted(set(valsA+valsR)); bestacc=0; bestt=None; bestdir=None
    for t in allv:
        for dir in ['R>','R<']:
            if dir=='R>': acc=sum(v>t for v in valsR)+sum(v<=t for v in valsA)
            else: acc=sum(v<t for v in valsR)+sum(v>=t for v in valsA)
            if acc>bestacc: bestacc=acc; bestt=t; bestdir=dir
    best.append((bestacc/len(cand),name,bestdir,bestt,min(valsR),max(valsR),min(valsA),max(valsA)))
for b in sorted(best,reverse=True)[:15]: print(b)
