use rand::{Rng, RngCore, Error};
use std::collections::VecDeque;
struct Stub { q: VecDeque<u64>, n: u32 }
impl RngCore for Stub {
 fn next_u32(&mut self)->u32 { self.next_u64() as u32 }
 fn next_u64(&mut self)->u64 { self.n+=1; self.q.pop_front().unwrap_or(0x8000000000000000) }
 fn fill_bytes(&mut self,dest:&mut[u8]) { for i in 0..dest.len() { dest[i]=(self.next_u64()>>((i%8)*8)) as u8; } }
 fn try_fill_bytes(&mut self,dest:&mut[u8])->Result<(),Error> { self.fill_bytes(dest); Ok(()) }
}
fn test(x:u64,lo:i64,hi:i64)->(i64,u32){
  let mut s=Stub{q:VecDeque::from(vec![x]),n:0};
  let v=s.gen_range(lo..=hi);
  (v,s.n)
}
fn main(){
  // sweep high bits: x = k * 2^60
  for k in 0..16 {
    let x=(k as u64)<<60;
    println!("k={} x={:016x} -> {:?}",k,x,test(x,0,9));
  }
  // sweep fraction finely around areas
  for i in 0..=20 {
    let x=((i as u128)*(u64::MAX as u128)/20) as u64;
    println!("frac {}/20 x={:016x} -> {:?}",i,x,test(x,0,9));
  }
  // specific candidates from chacha seed42 first
  for x in [0xae90bfb5395d5ba1u64,0xf3453fc625799188,0x6d71b708c5b6538c,0x49e149d8bcb642b0] {
    println!("cand {:016x} -> {:?}",x,test(x,0,9));
  }
}
EOF
