# ---------- AST nodes ----------
class Node:
    __slots__=("kind","pos","a","b","c","d")
    def __init__(self,kind,pos,a=None,b=None,c=None,d=None):
        self.kind=kind; self.pos=pos; self.a=a; self.b=b; self.c=c; self.d=d
    def __repr__(self): return f"Node({self.kind},{self.a!r},{self.b!r},{self.c!r},{self.d!r})"

# Blocks are Node('block',pos, statements list, declarations_or_None)
# Identifiers represented as (name_or_None, Pos)

class WordPart:
    __slots__=("kind","data","pos","active")
    def __init__(self,kind,data,pos=None,active=None): self.kind=kind; self.data=data; self.pos=pos; self.active=active

class CmdWord:
    __slots__=("pos","fragments","parts","is_number","number_text","resolved_parts")
    def __init__(self,pos,fragments=None,parts=None,is_number=False,number_text=None):
        self.pos=pos; self.fragments=fragments or []; self.parts=parts or []; self.is_number=is_number; self.number_text=number_text; self.resolved_parts=None

# Lexer
KEYWORDS={"let","function","end","if","then","else","elseif","while","do","for","in","return","break","and","or","not","true","false","nil","self"}

def is_ident_start(b): return b==95 or (65<=b<=90) or (97<=b<=122)
def is_ident_char(b): return is_ident_start(b) or (48<=b<=57)
def is_valid_ident_name(s):
    return bool(s) and is_ident_start(ord(s[0])) and all(is_ident_char(ord(c)) for c in s)

def error_char_text(b):
    # format a single byte as in error messages between single quotes (without quotes here)
    if b==10: return "\\n"
    if b==9: return "\\t"
    if b==13: return "\\r"
    if b==0: return "\\0"
    if b==92: return "\\\\"
    if b==39: return "\\'"
    if b==34: return '\\"'
    if 32<=b<127: return chr(b)
    if b<32 or b==127: return "\\u{%x}"%b
    return chr(b)  # unicode codepoint equal to byte

class Token:
    __slots__=("kind","pos","text","value")
    def __init__(self,kind,pos,text,value=None): self.kind=kind; self.pos=pos; self.text=text; self.value=value

class LexErrorItem:
    __slots__=("pos","msg")
    def __init__(self,pos,msg): self.pos=pos; self.msg=msg

ESCAPE_MAP={48:0,110:10,116:9,92:92,39:39,34:34}

class Lexer:
    def __init__(self,source:bytes,filename:str):
