        if b==10: self.line+=1; self.col=0
        else: self.col+=1
        return b
    def add_token(self,kind,pos,text,value=None): self.items.append(Token(kind,pos,text,value))
    def add_error(self,pos,msg): self.items.append(LexErrorItem(pos,msg))
    def err_unexpected_char(self,pos,b):
