    def err_eof(self,pos=None):
        self.add_error(pos or self.pos(), "unexpected end of file.")
    # escapes
    def parse_escape_normal(self):
        # current char is backslash; returns byte or None(invalid)
        slash=self.pos(); self.advance()
        if self.eof():
            self.err_eof(); return None
        b=self.advance()
        if b in ESCAPE_MAP: return ESCAPE_MAP[b]
        self.add_error(slash, f"invalid escape sequence '\\{error_char_text(b)}'.")
        return None
    def allowed_escape(self,ctx,b):
        if b in ESCAPE_MAP:
            if ctx=='single' and b==34: return False
            if ctx=='double' and b==39: return False
            return True
        if ctx=='double' and b==36: return True
        if ctx=='unquoted' and b in (36,32,59,60,62,63,35): return True
        return False
    def escape_value(self,ctx,b):
        if b in ESCAPE_MAP: return ESCAPE_MAP[b]
        return b
    def parse_escape_expansion(self,ctx,append_fn):
        # returns True if should continue fragment, False if hit EOF
        slash=self.pos(); self.advance()
        if self.eof():
            self.err_eof(); return False
        b=self.advance()
        if self.allowed_escape(ctx,b):
            append_fn(self.escape_value(ctx,b)); return True
        seq=bytearray(b'\\'); seq.append(b)
        self.add_error(slash, f"invalid escape sequence '{self._seq_text(seq)}'.")
        # bad-escape accumulation mode
        while True:
            if self.eof():
                self.err_eof(); return False
            nb=self.peek()
            # In unquoted context, some terminators? Valid escape code bytes terminate.
            if self.allowed_escape(ctx,nb):
                self.advance(); append_fn(self.escape_value(ctx,nb)); return True
            # consume and report cumulative
            self.advance(); seq.append(nb)
            self.add_error(slash, f"invalid escape sequence '{self._seq_text(seq)}'.")
    def _seq_text(self,seq):
        out=[]
        for b in seq:
            if b==92 and len(out)==0: out.append('\\')
            else: out.append(error_char_text(b) if b!=92 else '\\\\')
