            if self.eof():
                self.add_error(start,"unexpected '\\n'."); return
            nb=self.advance()
            if not (48<=nb<=57):
                self.add_error(start, f"unexpected '{error_char_text(nb)}'."); return
            while not self.eof() and 48<=self.peek()<=57: self.advance()
        if self.peek() in (101,69):
            is_float=True; self.advance()
            if self.eof():
                self.add_error(start,"unexpected '\\n'."); return
            nb=self.advance()
            if not (48<=nb<=57):
                self.add_error(start, f"unexpected '{error_char_text(nb)}'."); return
            while not self.eof() and 48<=self.peek()<=57: self.advance()
