            self.add_token('int',start,str(val),val)
    def lex_string(self):
        start=self.pos(); self.advance() # "
        out=bytearray()
        while True:
            if self.eof():
                self.err_eof(); return
            b=self.peek()
            if b==34:
                self.advance(); break
            if b==92:
                v=self.parse_escape_normal()
                if v is not None: out.append(v)
                if self.eof() and v is None:
                    return
            else:
                out.append(self.advance())
        data=bytes(out)
        self.add_token('string',start,format_string_literal(data),data)
    def lex_char(self):
        start=self.pos(); self.advance() # '
        if self.eof():
            self.err_eof(); return
        if self.peek()==39:
            self.advance(); self.add_error(start,"empty char literal."); return
        # first unit
        if self.peek()==92:
            v=self.parse_escape_normal(); val=0 if v is None else v
