    def lex_identifier(self):
        start=self.pos(); si=self.i
        while not self.eof() and is_ident_char(self.peek()): self.advance()
        name=self.src[si:self.i].decode('ascii')
        if name in KEYWORDS:
            self.add_token(name,start,name,name)
        else:
            self.add_token('ident',start,name,name)
    def skip_ws_comments(self):
        while not self.eof():
            b=self.peek()
            if b in (32,9,10,13,12):
                self.advance(); continue
            if b==35:
                while not self.eof() and self.peek()!=10: self.advance()
                continue
            break
    def run(self):
        while True:
            self.skip_ws_comments()
            if self.eof():
                if self.mode_stack[-1]=='command':
                    self.err_eof()
                break
            if self.mode_stack[-1]=='command':
                self.lex_command_token()
            else:
                self.lex_normal_token()
