    def lex_normal_token(self):
        start=self.pos(); b=self.peek()
        if is_ident_start(b): self.lex_identifier(); return
        if 48<=b<=57: self.lex_number(); return
        if b==34: self.lex_string(); return
        if b==39: self.lex_char(); return
        # symbols
        two=self.src[self.i:self.i+2]
        if two==b'${':
            self.advance(); self.advance(); self.add_token('${',start,'${'); self.mode_stack.append('command'); return
        if two==b'&{':
            self.advance(); self.advance(); self.add_token('&{',start,'&{'); self.mode_stack.append('command'); return
        if two==b'@[':
            self.advance(); self.advance(); self.add_token('@[',start,'@['); return
        if b==123:
