        self.advance(); self.err_unexpected_char(start,b); return
    # command mode
    def lex_command_token(self):
        start=self.pos(); b=self.peek()
        if b==125:
            self.advance(); self.add_token('}',start,'}');
            if len(self.mode_stack)>1: self.mode_stack.pop()
            return
