                raise RustPanic("src/syntax/lexer/automata/expansion.rs:87:17","not yet implemented")
            if b==123:
                raise RustPanic("src/syntax/lexer/automata/expansion.rs:91:17","not yet implemented")
            append_raw(self.advance(),True)
        flush_raw()
        word=self._make_word(start,fragments)
        self.add_token('word',start,word_display(word),word)
