                if self.eof(): self.err_eof(); return None
                if self.peek()==39: self.advance(); break
                if self.peek()==92:
                    ok=self.parse_escape_expansion('single', lambda v: out.append(v))
                    if not ok: return None
                else:
                    out.append(self.advance())
            return ('single',bytes(out))
        else:
            subs=[]; raw=bytearray()
            def flush():
                nonlocal raw
                if raw: subs.append(('raw',bytes(raw))); raw=bytearray()
            while True:
                if self.eof(): self.err_eof(); return None
                if self.peek()==34: self.advance(); break
                if self.peek()==36:
                    flush(); var=self.lex_expansion_var()
                    if var is None:
                        if self.eof(): return None
                    else: subs.append(var)
                    continue
                if self.peek()==92:
                    ok=self.parse_escape_expansion('double', lambda v: raw.append(v))
                    if not ok: return None
                else:
                    raw.append(self.advance())
            flush()
            return ('double',subs)
    def lex_expansion_var(self):
        start=self.pos(); self.advance() # $
        if self.peek()==123:
            self.advance(); si=self.i
            while not self.eof() and self.peek()!=125: self.advance()
            if self.eof(): self.err_eof(); return None
            name_bytes=self.src[si:self.i]; self.advance() # }
            name=name_bytes.decode('utf-8','replace')
            if is_valid_ident_name(name) and name not in KEYWORDS:
                return ('var',name,start)
            self.add_error(start, f"invalid identifier '{lossy_utf8(name_bytes)}'.")
            return None
        # unbraced
        if self.eof():
            self.add_error(start, "invalid identifier ''." ); return None
        b=self.peek()
        if is_ident_start(b):
            si=self.i
            while not self.eof() and is_ident_char(self.peek()): self.advance()
            name=self.src[si:self.i].decode('ascii')
            if name in KEYWORDS:
                self.add_error(start, f"invalid identifier '{name}'."); return None
            return ('var',name,start)
        # invalid: consume one char (if $ then also following ident chars form candidate)
        if b==36:
            self.advance(); si=self.i
            while not self.eof() and is_ident_char(self.peek()): self.advance()
            cand="$"+self.src[si:self.i].decode('utf-8','replace')
            self.add_error(start, f"invalid identifier '{cand}'."); return None
        self.advance()
        cand=chr(b) if 32<=b<127 else error_char_text(b)
        self.add_error(start, f"invalid identifier '{cand}'.")
        return None
    def _make_word(self,start,fragments):
        parts=[]
        for frag in fragments:
            if frag[0]=='raw':
                data,active=frag[1],frag[2]
                if data: parts.append(WordPart('lit',data,start,active))
            elif frag[0]=='single':
                if frag[1]: parts.append(WordPart('lit',frag[1],start,bytes(len(frag[1]))))
            elif frag[0]=='double':
                for sub in frag[1]:
                    if sub[0]=='raw':
                        if sub[1]: parts.append(WordPart('lit',sub[1],start,bytes(len(sub[1]))))
                    elif sub[0]=='var':
                        parts.append(WordPart('var',sub[1],sub[2]))
            elif frag[0]=='var':
                parts.append(WordPart('var',frag[1],frag[2]))
        return CmdWord(start,fragments,parts)

def _esc_content(data:bytes):
    s=lossy_utf8(data)
    return ''.join(rust_escape_debug_char(c) for c in s)

def word_display(word):
    if word.is_number: return word.number_text
    out=[]
    for frag in word.fragments:
        if frag[0]=='raw': out.append(_esc_content(frag[1]))
        elif frag[0]=='single': out.append("'"+_esc_content(frag[1])+"'")
        elif frag[0]=='double':
            inner=[]
            for sub in frag[1]:
                if sub[0]=='raw': inner.append(_esc_content(sub[1]))
                else: inner.append("${{"+sub[1]+"}}")
            out.append('"'+''.join(inner)+'"')
        elif frag[0]=='var': out.append("${{"+frag[1]+"}}")
    return ''.join(out)

def word_template(word, program=False):
    # template bytes for AST display: literal bytes + ${name} or ${#slot}
    out=bytearray()
    parts=word.resolved_parts if (program and word.resolved_parts is not None) else word.parts
    if word.is_number:
        return word.number_text.encode()
    for p in parts:
        if p.kind=='lit': out+=p.data
        elif p.kind=='var':
            if program: out+=("${#%d}"%p.data).encode()
            else: out+=("${"+p.data+"}").encode()
        elif p.kind=='slot':
            out+=("${#%d}"%p.data).encode()
    # If parts empty but fragments were quoted empty, template is empty (displays "")
    return bytes(out)

