        t=self.cur()
        k=t.kind
        if k=='int' or k=='float' or k=='string' or k=='char':
            self.advance(); return Node('literal',t.pos,t.value)
        if k=='true': self.advance(); return Node('literal',t.pos,True)
        if k=='false': self.advance(); return Node('literal',t.pos,False)
        if k=='nil': self.advance(); return Node('literal',t.pos,None)
        if k=='ident': self.advance(); return Node('var',t.pos,t.value)
        if k=='self': self.advance(); return Node('self',t.pos)
        if k=='(':
            self.advance(); e=self.parse_expression(); self.expect(')',"')'"); return e
        if k=='[':
            self.advance(); elems=self.parse_expr_list(']'); return Node('array',t.pos,elems)
        if k=='@[':
            return self.parse_dict()
        if k=='function':
            self.advance(); return self.parse_function_rest(t.pos)
        if k=='if':
            return self.parse_if()
        if k in ('{','${','&{'):
            return self.parse_command_block()
