            if self.at_eof(): break
            # key: identifier (consume literal tokens erroneously like original recovery)
            if self.at('ident'):
                kt=self.advance(); key=kt.value; kpos=kt.pos
            else:
                kpos=self.cur().pos; key=None; self.error_expected("identifier")
                if self.cur().kind in ('int','float','string','char'): self.advance()
            if self.at(':'): self.advance()
            else:
                self.error_expected("':'"); key=None
            val=self.parse_expression()
            entries.append((key,kpos,val))
            if self.at(','):
                self.advance()
                if self.at(']'): break
                continue
            break
