    def token_to_word(self,tok):
        if tok.kind=='word': return tok.value
        if tok.kind in ('int','float'):
            txt=tok.text.encode()
            w=CmdWord(tok.pos,[('raw',txt,bytes([1]*len(txt)))],[WordPart('lit',txt,tok.pos,bytes([1]*len(txt)))],True,tok.text)
            return w
        if tok.kind=='string':
            return CmdWord(tok.pos,[('double',[('raw',tok.value)])],[WordPart('lit',tok.value,tok.pos,bytes(len(tok.value))) ] if tok.value else [])
        if tok.kind=='char':
            data=bytes([tok.value.v]); return CmdWord(tok.pos,[('single',data)],[WordPart('lit',data,tok.pos,bytes(1))])
        return None
    def parse_redirect(self,source_fd):
        optok=self.advance(); op=optok.kind
        if op in ('>','>>') and self.at('int'):
            tt=self.advance(); target=('fd',tt.value,tt.pos)
        else:
            w=self.token_to_word(self.cur()) if not self.at_eof() else None
            if w is not None:
                self.advance(); target=('word',w)
            else:
                self.error_expected("argument"); target=('ill',None)
        return Node('redir',optok.pos,op,source_fd,target)
    def parse_command(self):
        start_pos=self.cur().pos
        words=[]; redirects=[]; in_redir=False; tryflag=False
        if self.at_eof():
            self.error_expected("argument")
            return Node('command',start_pos,words,redirects,False)
        while not self.at_eof():
            t=self.cur()
            if t.kind in (';','|','?','}'): break
            if t.kind=='int' and self.peek().kind in ('>','>>','<','<<'):
                fdtok=self.advance(); op=self.cur()
                if op.kind in ('<','<<'):
                    self.errors.append(StaticError(op.pos, f"unexpected '{op.text}', expected output redirection"))
                    self.advance()
                    if self.token_to_word(self.cur()) is not None:
                        self.error_expected("output redirection"); self.advance()
                    in_redir=True; continue
                redirects.append(self.parse_redirect(fdtok.value)); in_redir=True; continue
            if t.kind in ('>','>>','<','<<'):
                redirects.append(self.parse_redirect(None)); in_redir=True; continue
            w=self.token_to_word(t)
            if w is not None:
                if in_redir:
                    self.error_expected("output redirection")
                self.advance(); words.append(w); continue
            # cannot be an argument
            if not words and not redirects:
                self.error_expected("argument"); self.advance(); continue
            break
        if self.at('?'):
            self.advance(); tryflag=True
        return Node('command',start_pos,words,redirects,tryflag)
    def parse_pipeline(self):
        cmds=[self.parse_command()]
        while self.at('|'):
            self.advance(); cmds.append(self.parse_command())
        return cmds
    def parse_command_block(self):
        open_tok=self.advance()
        kind={'{':'plain','${':'capture','&{':'async'}[open_tok.kind]
        pipelines=[]
        if self.at('}'):
            self.errors.append(StaticError(self.cur().pos,"empty command block"))
            self.advance(); return Node('cmdblock',open_tok.pos,kind,pipelines)
        while not self.at_eof() and not self.at('}'):
            pipelines.append(self.parse_pipeline())
            if self.at(';'):
                self.advance(); continue
            if self.at('}') or self.at_eof(): break
            self.error_expected("'}'")
            if not self.at_eof(): self.advance()
        if self.at('}'): self.advance()
        else: self.error_expected("'}'")
        return Node('cmdblock',open_tok.pos,kind,pipelines)

