# ---------- Compilation ----------
class Compiled:
    __slots__=("filename","lex_items","ast","syntax_errors","semantic_errors","program")
    def __init__(s,filename,lex_items,ast,syntax,semantic,program): s.filename=filename; s.lex_items=lex_items; s.ast=ast; s.syntax_errors=syntax; s.semantic_errors=semantic; s.program=program

def compile_source(source:bytes,filename:str):
    lexer=Lexer(source,filename); items=lexer.run()
    lex_errors=[]; tokens=[]
    for it in items:
        if isinstance(it,LexErrorItem): lex_errors.append(StaticError(it.pos,it.msg))
        else: tokens.append(it)
    eof_pos=lexer.pos()
    parser=Parser(tokens,filename,eof_pos); ast=parser.parse()
    syntax_errors=lex_errors+parser.errors
    resolver=Resolver(); resolved=resolver.resolve_root(ast)
    program=None if (resolver.errors or resolver.blocked) else resolved
    return Compiled(filename,items,ast,syntax_errors,resolver.errors,program)

def sort_errors(errors):
    def key(e):
        if e.pos is None: return (1,0,0)
        return (0,e.pos.line,e.pos.col)
    return sorted(errors,key=key)  # stable

def format_error_reports(syntax_errors,semantic_errors):
    out=[]
    for errs,label in [(syntax_errors,"syntax"),(semantic_errors,"semantic")]:
        if not errs: continue
        ser=sort_errors(errs)
        for e in ser[:20]:
            if e.pos is None: out.append(f"Error: {e.msg}\n")
            else: out.append(f"Error: {e.pos.text()} - {e.msg}\n")
        if len(ser)>20:
            out.append(f"20 more supressed {label} errors\n")
    return ''.join(out)

