            raise ReturnFlow(self.eval_expr(stmt.a,frame))
        if k=='break': raise BreakFlow()
        if k=='while':
            while True:
                cond=self.eval_expr(stmt.a,frame)
                if type(cond) is not bool:
                    self.panic(stmt.a.pos, f"condition ({format_value(cond)}) is not a boolean")
                if not cond: break
