# ---------- Command expansion & execution ----------
class PatVal:
    __slots__=("data","active")
    def __init__(self,data=b'',active=b''):
        self.data=bytearray(data); self.active=bytearray(active)
    def __add__(self,other):
        return PatVal(bytes(self.data)+bytes(other.data), bytes(self.active)+bytes(other.active))

def _scalar_expansion_bytes(interp,v,pos):
    if v is None: return b''
    if type(v) is bool: return b'true' if v else b'false'
    if type(v) is int: return str(v).encode()
    if type(v) is float: return rust_float_debug(v).encode()
    if isinstance(v,Char): return bytes([v.v])
    if type(v) is bytes: return v
    _type_panic(pos,v,"nil, bool, int, float, byte or string")

def expand_word_patterns(interp,word,frame):
    if word.is_number:
        txt=word.number_text.encode(); return [PatVal(txt,bytes([1]*len(txt)))]
    parts=word.resolved_parts if word.resolved_parts is not None else word.parts
    results=[]
    for part in parts:
        if part.kind=='lit':
            active=part.active if part.active is not None else bytes(len(part.data))
            alts=[PatVal(part.data,active)]
        else:
            if part.kind=='slot': v=frame[part.data].v
            else: v=None
