def _json_encode_value(v,indent=0):
    if v is None: return "null"
    if type(v) is bool: return "true" if v else "false"
    if type(v) is int: return str(v)
    if type(v) is float:
        if not math.isfinite(v): return "null"
        return rust_float_debug(v)
    if isinstance(v,Char): return _json_escape_str(chr(v.v))
    if type(v) is bytes: return _json_escape_str(lossy_utf8(v))
    if isinstance(v,HArray):
        if not v.items: return "[]"
        inner=",\n".join("  "*(indent+1)+_json_encode_value(x,indent+1) for x in v.items)
        return "[\n"+inner+"\n"+"  "*indent+"]"
    if isinstance(v,HDict):
        if not v.map: return "{}"
        parts=[]
        for k,val in v.map.values():
            parts.append("  "*(indent+1)+_json_escape_str(lossy_utf8(k))+": "+_json_encode_value(val,indent+1))
        return "{\n"+",\n".join(parts)+"\n"+"  "*indent+"}"
    raise ValueError("bad")

def _json_validate(v):
    if v is None or type(v) in (bool,int,float) or isinstance(v,(Char,bytes)): return
    if isinstance(v,HArray):
        for x in v.items: _json_validate(x)
        return
    if isinstance(v,HDict):
        for k,val in v.map.values():
            if type(k) is not bytes: raise ValueError("bad key")
            _json_validate(val)
        return
    raise ValueError("bad")

class JsonParser:
    def __init__(self,text):
        self.s=text; self.i=0; self.n=len(text)
    def err(self,msg,at=None):
        idx=self.i if at is None else at
        line=self.s.count('\n',0,idx)+1
        last=self.s.rfind('\n',0,idx)
        col=idx-last
        # serde col is 0 at very start/EOF, otherwise idx-last (1-based for first char)
        raise JsonError(f"{msg} at line {line} column {col}")
    def ws(self):
        while self.i<self.n and self.s[self.i] in ' \t\n\r': self.i+=1
    def parse(self):
        self.ws()
        if self.i>=self.n: self.err("EOF while parsing a value",0)
        v=self.value(0); self.ws()
        if self.i<self.n: self.err("trailing characters", self.i+1-1)  # col calc: rfind gives idx-last; for "1 2" idx2 -> col3 if last=-1 -> 3 good when at=2; adjust below
        return v
    def value(self,depth):
        if depth>128: self.err("recursion limit exceeded")
        if self.i>=self.n: self.err("EOF while parsing a value")
        c=self.s[self.i]
        if c=='n': return self.literal("null",None)
        if c=='t': return self.literal("true",True)
        if c=='f': return self.literal("false",False)
        if c=='"': return self.string()
        if c=='[': return self.array(depth)
        if c=='{': return self.obj(depth)
        if c=='-' or c.isdigit(): return self.number()
        self.err("expected value", self.i+1)
    def literal(self,word,val):
        if self.s.startswith(word,self.i): self.i+=len(word); return val
        # serde: for input "invalid" starting i -> expected value handled before; partial like nul -> EOF...
        if word.startswith(self.s[self.i:]): self.i=self.n; self.err("EOF while parsing a value")
        self.err("expected value",self.i+1)
    def number(self):
        start=self.i
        if self.s[self.i]=='-': self.i+=1
        if self.i>=self.n or not self.s[self.i].isdigit(): self.err("expected value",start+1)
        if self.s[self.i]=='0': self.i+=1
        else:
            while self.i<self.n and self.s[self.i].isdigit(): self.i+=1
        is_float=False
        if self.i<self.n and self.s[self.i]=='.':
            is_float=True; self.i+=1
            if self.i>=self.n or not self.s[self.i].isdigit(): self.err("expected value",self.i)
            while self.i<self.n and self.s[self.i].isdigit(): self.i+=1
        if self.i<self.n and self.s[self.i] in 'eE':
            is_float=True; self.i+=1
            if self.i<self.n and self.s[self.i] in '+-': self.i+=1
            if self.i>=self.n or not self.s[self.i].isdigit(): self.err("expected value",self.i)
            while self.i<self.n and self.s[self.i].isdigit(): self.i+=1
        tok=self.s[start:self.i]
        if not is_float:
            v=int(tok)
            if tok=="-0": return -0.0
            if v<I64_MIN or v>I64_MAX:
                # serde_json would parse huge positive as u64/float depending magnitude; out-of-range for i64 visitor in observed range
                if 0<=v<=18446744073709551615 or v<I64_MIN:
                    self.err("out of range integral type conversion attempted",self.i)
                return float(tok)
            return v
        return float(tok)
    def string(self):
        # returns bytes (utf-8 encoded)
        self.i+=1; out=[]
        while True:
            if self.i>=self.n: self.err("EOF while parsing a string")
            c=self.s[self.i]
            if c=='"': self.i+=1; break
            if c=='\\':
                self.i+=1
                if self.i>=self.n: self.err("EOF while parsing a string")
                e=self.s[self.i]; self.i+=1
                mp={'"':'"','\\':'\\','/':'/','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t'}
                if e in mp: out.append(mp[e])
                elif e=='u':
                    if self.i+4>self.n: self.err("EOF while parsing a string")
                    hexs=self.s[self.i:self.i+4]
                    if not re.fullmatch(r'[0-9a-fA-F]{4}',hexs): self.err("invalid escape",self.i)
                    code=int(hexs,16); self.i+=4
                    if 0xD800<=code<=0xDBFF:
                        if self.s[self.i:self.i+2]=='\\u' and self.i+6<=self.n and re.fullmatch(r'[0-9a-fA-F]{4}',self.s[self.i+2:self.i+6]):
                            code2=int(self.s[self.i+2:self.i+6],16)
                            if 0xDC00<=code2<=0xDFFF:
                                out.append(chr(0x10000+((code-0xD800)<<10)+(code2-0xDC00))); self.i+=6
                            else: self.err("lone leading surrogate in hex escape",self.i)
                        else: self.err("lone leading surrogate in hex escape",self.i)
                    elif 0xDC00<=code<=0xDFFF:
                        # serde allows? it errors with lone leading surrogate message in some versions; approximate replacement
                        out.append('\ufffd')
                    else: out.append(chr(code))
                else: self.err("invalid escape",self.i)
                continue
            if ord(c)<0x20: self.err("control character (\\u0000-\\u001F) found while parsing a string",self.i)
            out.append(c); self.i+=1
