            if self.i>=self.n: self.err("EOF while parsing a list")
            arr.items.append(self.value(depth+1)); self.ws()
            if self.i>=self.n: self.err("EOF while parsing a list")
            if self.s[self.i]==',':
                self.i+=1; self.ws()
                if self.i<self.n and self.s[self.i]==']': self.err("trailing comma",self.i+1)
                continue
            if self.s[self.i]==']': self.i+=1; break
            self.err("expected `,` or `]`",self.i)
