    def obj(self,depth):
        self.i+=1; d=HDict(); self.ws()
        if self.i<self.n and self.s[self.i]=='}': self.i+=1; return d
        while True:
            self.ws()
            if self.i>=self.n: self.err("EOF while parsing an object")
            if self.s[self.i]!='"': self.err("key must be a string",self.i)
            key=self.string(); self.ws()
            if self.i>=self.n: self.err("EOF while parsing an object")
            if self.s[self.i]!=':': self.err("expected `:`",self.i)
            self.i+=1; self.ws(); val=self.value(depth+1); dict_set(d,key,val); self.ws()
            if self.i>=self.n: self.err("EOF while parsing an object")
            if self.s[self.i]==',':
                self.i+=1; self.ws()
                if self.i<self.n and self.s[self.i]=='}': self.err("trailing comma",self.i+1)
                continue
            if self.s[self.i]=='}': self.i+=1; break
            self.err("expected `,` or `}`",self.i)
        return d

