# ---------- Regex ----------
class RegexErrorVal(Exception):
    __slots__=("text",)
    def __init__(self,text): self.text=text

def _regex_error(pat,span_start,span_len,msg):
    text=f"regex parse error:\n    {pat}\n    {' '*span_start}{'^'*max(1,span_len)}\nerror: {msg}"
    raise RegexErrorVal(text)

def _translate_regex(pat):
    # pat is str (latin1 decoded). Returns python pattern str.
    out=[]; i=0; n=len(pat); group_stack=[]; in_class=False; class_start=-1
    # validate flavour basics in scan
    while i<n:
        c=pat[i]
        if in_class:
            if c=='\\' and i+1<n:
                e=pat[i+1]
                if e in 'dwsDWS': out.append('\\'+e)
                elif e=='e': out.append('\\x1b')
                elif e in '123456789': _regex_error(pat,i,2,"backreferences are not supported")
                elif e.isalnum() and e not in 'abfnrtv': _regex_error(pat,i+1,1,"unrecognized escape sequence")
                else: out.append('\\'+e)
                i+=2; continue
            if c==']': in_class=False; out.append(c); i+=1; continue
            out.append(c); i+=1; continue
        if c=='[':
            in_class=True; class_start=i; out.append(c)
            if i+1<n and pat[i+1]=='^': out.append('^'); i+=1
            i+=1; continue
        if c=='\\':
            if i+1>=n: _regex_error(pat,i,1,"unrecognized escape sequence")
            e=pat[i+1]
            if e in 'dwsDWSbBA': out.append('\\'+e); i+=2; continue
            if e=='z': out.append('\\Z'); i+=2; continue
            if e=='e': out.append('\\x1b'); i+=2; continue
            if e=='p' or e=='P':
                # find span
                if i+2<n and pat[i+2]=='{':
                    j=pat.find('}',i+3); span=(j-i+1) if j>=0 else 2
                    _regex_error(pat,i,span,"Unicode property not found")
                _regex_error(pat,i,2,"Unicode property not found")
            if e=='x':
                if i+2<n and pat[i+2]=='{':
                    j=pat.find('}',i+3)
                    if j<0: _regex_error(pat,i,2,"unclosed hexadecimal literal")
                    hexs=pat[i+3:j]
                    try: out.append(chr(int(hexs,16)))
                    except Exception: _regex_error(pat,i,j-i+1,"invalid hexadecimal digit")
                    i=j+1; continue
                out.append('\\x'); i+=2; continue
            if e in '123456789': _regex_error(pat,i,2,"backreferences are not supported")
            if e=='u' or e=='U':
                _regex_error(pat,i,2,"Unicode-aware property matching is not available")
            if e.isalnum() and e not in 'abfnrtv0': _regex_error(pat,i+1,1,"unrecognized escape sequence")
            out.append('\\'+e); i+=2; continue
        if c=='(':
            # group syntax
            if pat.startswith('(?P<',i):
                j=pat.find('>',i+4)
                if j<0: _regex_error(pat,i,1,"unclosed capture group name")
                out.append('(?P<'+pat[i+4:j]+'>'); group_stack.append(i); i=j+1; continue
            if pat.startswith('(?',i):
                # flags until ) or :
                j=i+2; flags=[]
                while j<n and pat[j] not in '):': flags.append(pat[j]); j+=1
                if j>=n: _regex_error(pat,i,1,"unclosed group")
                flagstr=''.join(flags)
                # check invalid flag chars (Rust allows i,m,s,x,u,U and -)
                base=flagstr.split('-')[0]
                for k,ch in enumerate(flagstr):
                    if ch not in 'imsxuU-': _regex_error(pat,i+2+k,1,"unrecognized flag")
                if 'i' in base:
                    _regex_error(pat,j+1 if j+1<n else j,1,"Unicode-aware case insensitivity matching is not available (make sure the unicode-case feature is enabled)")
                if 'u' in base:
                    _regex_error(pat,i+2+flagstr.index('u'),1,"Unicode-aware property matching is not available")
                # translate: U not supported by python - strip it (best effort)
                pflags=''.join(ch for ch in flagstr if ch in 'msx-')
                if pat[j]==')': out.append('(?' + pflags + ')')
                else: out.append('(?' + pflags + ':'); group_stack.append(i)
                i=j+1; continue
            group_stack.append(i); out.append('('); i+=1; continue
        if c==')':
            if not group_stack: _regex_error(pat,i,1,"unopened group")
            group_stack.pop(); out.append(')'); i+=1; continue
        if c in '*+?':
            # missing expression if at start or previous meaningful char is ( or |
            prev=''.join(out).rstrip()
            if not out or prev.endswith('(') or prev.endswith('|') or prev.endswith(':'):
                _regex_error(pat,i,1,"repetition operator missing expression")
            out.append(c); i+=1; continue
        if c=='{':
            m=re.match(r'\{(\d+)(?:,(\d*))?\}',pat[i:])
            if m:
                a=int(m.group(1)); b=m.group(2)
                if b not in (None,'') and int(b)<a:
                    _regex_error(pat,i,len(m.group(0)),"invalid repetition count range, the start must be <= the end")
                prev=''.join(out).rstrip()
                if not out or prev.endswith('(') or prev.endswith('|'):
                    _regex_error(pat,i,1,"repetition operator missing expression")
                out.append(m.group(0)); i+=len(m.group(0)); continue
            out.append('\\{'); i+=1; continue
        out.append(c); i+=1
    if in_class: _regex_error(pat,class_start,1,"unclosed character class")
    if group_stack: _regex_error(pat,group_stack[-1],1,"unclosed group")
    return ''.join(out)

class RegexObj:
    __slots__=("pat","cre")
    def __init__(self,pat_bytes):
        self.pat=pat_bytes.decode('latin1')
        translated=_translate_regex(self.pat)
        try:
            self.cre=re.compile(translated,re.ASCII)
        except re.error as ex:
            pos=getattr(ex,'pos',0) or 0
            _regex_error(self.pat,pos,1,ex.msg)
    def _finditer(self,text): return self.cre.finditer(text)

def _regex_expand(rep,match):
    out=[]; i=0
    groupindex=match.re.groupindex; ngroups=match.re.groups
    while i<len(rep):
        if rep[i]!='$': out.append(rep[i]); i+=1; continue
        if i+1<len(rep) and rep[i+1]=='$': out.append('$'); i+=2; continue
        # braced
        name=None; adv=0
        if i+1<len(rep) and rep[i+1]=='{':
            j=rep.find('}',i+2)
            if j>=0: name=rep[i+2:j]; adv=j+1
        if name is None:
            j=i+1
            while j<len(rep) and (rep[j].isalnum() or rep[j]=='_'): j+=1
            if j==i+1:
                out.append('$'); i+=1; continue
            name=rep[i+1:j]; adv=j
        val=''
        try:
            if name.isdigit():
                idx=int(name)
                if idx<=ngroups: val=match.group(idx) or ''
            elif name in groupindex:
                val=match.group(name) or ''
            elif name=='':
                val=match.group(0) or ''
        except Exception: val=''
        out.append(val); i=adv
    return ''.join(out)

