_B64_ALPHABET=b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
def _base64_decode(s):
    if len(s)%4==1:
        return HErrorVal(b"Encoded text cannot have a 6-bit remainder.",s)
    # strip trailing padding (up to 2 handled; extra '=' will be caught in body validation as it remains)
    body=s
    # Count trailing =
    body_stripped=body.rstrip(b'=')
    # If there were more than 2 padding chars, old crate treats excess '=' as invalid byte at position of 3rd? approximate by validation below on stripped if padding count>2
    if len(body)-len(body_stripped)>2:
        # position of first '=' that is beyond 2 from end
        idx=len(body_stripped)+2
        return HErrorVal(f"Invalid byte 61, offset {idx}.".encode(),s)
    for i,b in enumerate(body_stripped):
        if b not in _B64_ALPHABET:
            return HErrorVal(f"Invalid byte {b}, offset {i}.".encode(),s)
    # last symbol checks
    rem=len(body_stripped)%4
    if rem==1:
        return HErrorVal(b"Encoded text cannot have a 6-bit remainder.",s)
    if rem==2 and body_stripped:
        idx=len(body_stripped)-1; val=_B64_ALPHABET.index(body_stripped[idx])
        if val & 0x0f:
            return HErrorVal(f"Invalid last symbol {body_stripped[idx]}, offset {idx}.".encode(),s)
    if rem==3 and body_stripped:
        idx=len(body_stripped)-1; val=_B64_ALPHABET.index(body_stripped[idx])
        if val & 0x03:
            return HErrorVal(f"Invalid last symbol {body_stripped[idx]}, offset {idx}.".encode(),s)
    padded=body_stripped+b'='*((4-len(body_stripped)%4)%4)
    try:
        return base64.b64decode(padded,validate=True)
    except Exception:
        return HErrorVal(b"Encoded text cannot have a 6-bit remainder.",s)

